  return {
    pairedItem: { item: i },
    json: {
      fileName,
      baseName,
      outputFileName: baseName + '.xlsx',
      pages: item.json.numpages ?? null,
      characters: text.length,
      isProbablyScanned: text.length < 50,
      text
    }
  };
