const input = $json;

const required = [
  "vendor_name",
  "invoice_number",
  "invoice_date"
];

function isInvoice(obj) {
  return (
    obj &&
    typeof obj === "object" &&
    !Array.isArray(obj) &&
    required.every(field => field in obj)
  );
}

function findInvoice(obj) {
  if (isInvoice(obj)) {
    return obj;
  }

  if (!obj || typeof obj !== "object") {
    return null;
  }

  for (const value of Object.values(obj)) {
    const result = findInvoice(value);

    if (result) {
      return result;
    }
  }

  return null;
}

var invoice = findInvoice(input);

