function areRequiredFieldsPresent(invJsonObj, validationJson, requiredFields) {
    console.log("checking invoice required fields:");
    requiredFields.every(field => console.log("\n", field, ":", invJsonObj[field]));

    let valid =
        invJsonObj &&
        typeof invJsonObj === "object" &&
        !Array.isArray(invJsonObj) &&
        //requiredFields.every(field => field in invJsonObj) &&
        //requiredFields.every(field => invJsonObj[field])
        requiredFields.every(field => Object.prototype.hasOwnProperty.call(invJsonObj, field) &&
        invJsonObj[field] !== null &&
        invJsonObj[field] !== undefined &&
        String(invJsonObj[field]).trim() !== ''
        )
        ;

    if (valid) {
        validationJson.validation.required_fields.status = true;
        validationJson.validation.required_fields.msg = "";
    }
    else {
        validationJson.validation.required_fields.status = false;
    }
    return validationJson.validation.required_fields.status;
}

function invoiceSubTotalMatchesWithLineItemsTotal(invJsonObj, validationJson) {

    const lineItems = Array.isArray(invJsonObj.line_items)
        ? invJsonObj.line_items
        : [];

    // =========================================================
    // CASE 1: NO LINE ITEMS
    // =========================================================
    // If there are no line items, subtotal must NOT be present.
    // Invoice-level total is allowed.
    // Tax is optional.
    // =========================================================

    if (lineItems.length === 0) {

        const hasSubtotal =
            invJsonObj.subtotal !== undefined &&
            invJsonObj.subtotal !== null &&
            invJsonObj.subtotal !== "";

        if (hasSubtotal) {

            validationJson.validation.subtotals.status = false;
            validationJson.validation.subtotals.msg =
                "Invoice has no line items, therefore subtotal must not be present.";

            validationJson.validation.subtotals.calculated_subtotal = null;
            validationJson.validation.subtotals.stated_subtotal =
                Number(invJsonObj.subtotal);
            validationJson.validation.subtotals.difference = null;

            return false;
        }

        // No line items and no subtotal.
        // Subtotal validation is not applicable.
        validationJson.validation.subtotals.status = true;
        validationJson.validation.subtotals.msg = "";
        validationJson.validation.subtotals.calculated_subtotal = null;
        validationJson.validation.subtotals.stated_subtotal = null;
        validationJson.validation.subtotals.difference = null;

        return true;
    }


    // =========================================================
    // CASE 2: LINE ITEMS EXIST
    // =========================================================
    // Rules:
    //
    // - line_total is mandatory.
    //
    // - quantity and unit_price are independently optional.
    //
    //   quantity | unit_price | Allowed?
    //   ---------|------------|---------
    //   missing  | missing    | YES
    //   present  | missing    | YES
    //   missing  | present    | YES
    //   present  | present    | YES, and validate multiplication
    //
    // - Sum of line_total must equal invoice subtotal.
    // =========================================================

    let calculatedSubtotal = 0;

    for (let i = 0; i < lineItems.length; i++) {

        const line = lineItems[i];


        // -----------------------------------------------------
        // line_total is mandatory
        // -----------------------------------------------------

        const hasLineTotal =
            line.line_total !== undefined &&
            line.line_total !== null &&
            line.line_total !== "";

        if (!hasLineTotal) {

            validationJson.validation.subtotals.status = false;
            validationJson.validation.subtotals.msg =
                `Line item ${i + 1} is missing line_total.`;

            return false;
        }


        const lineTotal = Number(line.line_total);

        if (!Number.isFinite(lineTotal)) {

            validationJson.validation.subtotals.status = false;
            validationJson.validation.subtotals.msg =
                `Line item ${i + 1} has an invalid line_total.`;

            return false;
        }


        // -----------------------------------------------------
        // quantity and unit_price are independently optional.
        //
        // Only validate multiplication when BOTH are present.
        // -----------------------------------------------------

        const hasQuantity =
            line.quantity !== undefined &&
            line.quantity !== null &&
            line.quantity !== "";

        const hasUnitPrice =
            line.unit_price !== undefined &&
            line.unit_price !== null &&
            line.unit_price !== "";


        if (hasQuantity && hasUnitPrice) {

            const quantity = Number(line.quantity);
            const unitPrice = Number(line.unit_price);

            if (!Number.isFinite(quantity)) {

                validationJson.validation.subtotals.status = false;
                validationJson.validation.subtotals.msg =
                    `Line item ${i + 1} has an invalid quantity.`;

                return false;
            }


            if (!Number.isFinite(unitPrice)) {

                validationJson.validation.subtotals.status = false;
                validationJson.validation.subtotals.msg =
                    `Line item ${i + 1} has an invalid unit_price.`;

                return false;
            }


            const calculatedLineTotal =
                Math.round(quantity * unitPrice * 100) / 100;

            const lineTotalDifference =
                Math.round((calculatedLineTotal - lineTotal) * 100) / 100;


            if (Math.abs(lineTotalDifference) >= 0.01) {

                validationJson.validation.subtotals.status = false;
                validationJson.validation.subtotals.msg =
                    `Line item ${i + 1}: quantity × unit_price does not equal line_total.`;

                return false;
            }
        }


        // -----------------------------------------------------
        // line_total is always included in subtotal calculation
        // regardless of whether quantity/unit_price are present.
        // -----------------------------------------------------

        calculatedSubtotal += lineTotal;
    }


    // =========================================================
    // CASE 3: LINE ITEMS EXIST BUT SUBTOTAL IS MISSING
    // =========================================================

    const hasSubtotal =
        invJsonObj.subtotal !== undefined &&
        invJsonObj.subtotal !== null &&
        invJsonObj.subtotal !== "";

    if (!hasSubtotal) {

        validationJson.validation.subtotals.status = false;
        validationJson.validation.subtotals.msg =
            "Invoice has line items, therefore subtotal is required.";

        validationJson.validation.subtotals.calculated_subtotal =
            Math.round(calculatedSubtotal * 100) / 100;

        validationJson.validation.subtotals.stated_subtotal = null;
        validationJson.validation.subtotals.difference = null;

        return false;
    }


    // =========================================================
    // CASE 4: VALIDATE INVOICE SUBTOTAL
    // =========================================================

    const statedSubtotal = Number(invJsonObj.subtotal);

    if (!Number.isFinite(statedSubtotal)) {

        validationJson.validation.subtotals.status = false;
        validationJson.validation.subtotals.msg =
            "Invoice subtotal is invalid.";

        validationJson.validation.subtotals.calculated_subtotal =
            Math.round(calculatedSubtotal * 100) / 100;

        validationJson.validation.subtotals.stated_subtotal = null;
        validationJson.validation.subtotals.difference = null;

        return false;
    }


    calculatedSubtotal =
        Math.round(calculatedSubtotal * 100) / 100;

    const subtotalDifference =
        Math.round((calculatedSubtotal - statedSubtotal) * 100) / 100;


    validationJson.validation.subtotals.calculated_subtotal =
        calculatedSubtotal;

    validationJson.validation.subtotals.stated_subtotal =
        statedSubtotal;

    validationJson.validation.subtotals.difference =
        subtotalDifference;


    // ---------------------------------------------------------
    // Final subtotal comparison
    // ---------------------------------------------------------

    if (Math.abs(subtotalDifference) < 0.01) {

        validationJson.validation.subtotals.status = true;
        validationJson.validation.subtotals.msg = "";

        return true;

    } else {

        validationJson.validation.subtotals.status = false;
        validationJson.validation.subtotals.msg =
            "Invoice subtotal and calculated line items subtotal do not match.";

        return false;
    }
}

function concatValidationErrorMessages(validationJson) {
    let errorMsgs = "";
    if (!validationJson.validation.required_fields.status) {
        errorMsgs = errorMsgs.concat(validationJson.validation.required_fields.msg);
    }
    if (!validationJson.validation.subtotals.status) {
        errorMsgs = errorMsgs.concat(validationJson.validation.subtotals.msg);
    }
    return errorMsgs;
}


